## Search for an encounter seed that enters free spins under default encounter rules.
## Run: godot --path AXEL/axel_project --headless -s res://combat/test/find_free_spin_seed.gd
## Optional: --start=0 --end=12345 --step=1 (shard ranges across parallel processes)
##
## Uses one CombatRoot for the whole scan (fast). Disables symbol/transition FX so
## headless spin_sync does not race extra RNG draws from async drop tweens.

const CombatRootScene := preload("res://combat/scenes/combat_root.tscn")

const _MAX_SPIN_ITERS_PER_SEED := 2048
const _MAX_NO_PROGRESS_STREAK := 4


func _init() -> void:
	call_deferred("_main")


func _parse_cli() -> Dictionary:
	var start := 0
	var end := 12345
	var step := 1
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--start="):
			start = int(a.get_slice("=", 1))
		elif a.begins_with("--end="):
			end = int(a.get_slice("=", 1))
		elif a.begins_with("--step="):
			step = int(a.get_slice("=", 1))
	if step <= 0:
		step = 1
	return {"start": start, "end": end, "step": step}


func _main() -> void:
	var cli := _parse_cli()
	var start: int = cli["start"]
	var end: int = cli["end"]
	var step: int = cli["step"]
	if end < start:
		print("FOUND_SEED:-1 (invalid range: end < start)")
		quit(1)
		return

	var cr: CombatRoot = CombatRootScene.instantiate()
	root.add_child(cr)
	if not cr.is_node_ready():
		await cr.ready

	# Faster + deterministic headless: do not spawn async FX that call rng.randf().
	cr.enable_symbol_fx = false
	cr.enable_transition_fx = false
	# Keep default encounter_def / goal / spin_budget from combat_root.tscn.

	for seed in range(start, end + 1, step):
		cr.setup_new_grid(seed)
		var spin_iters := 0
		var no_progress := 0
		while not cr.is_encounter_complete():
			var spins_before: int = cr.get_spins_used()
			cr.spin_sync()
			if cr.free_spins.active:
				print("FOUND_SEED:%d SPIN:%d" % [seed, cr.get_spins_used()])
				quit(0)
				return
			if cr.is_encounter_complete():
				break
			if cr.get_spins_used() == spins_before:
				no_progress += 1
				if no_progress >= _MAX_NO_PROGRESS_STREAK:
					break
			else:
				no_progress = 0
			spin_iters += 1
			if spin_iters >= _MAX_SPIN_ITERS_PER_SEED:
				push_warning("find_free_spin_seed: safety cap seed=%d" % seed)
				break

	print("FOUND_SEED:-1")
	quit(1)

